theorem modelMeasure_apply (ν : Measure 𝓧) (p : ℝ → 𝓧 → ℝ) (θ : ℝ) {s : Set 𝓧}
    (hs : MeasurableSet s) :
    modelMeasure ν p θ s = ∫⁻ x in s, ENNReal.ofReal (p θ x) ∂ν

theorem isProbabilityMeasure_modelMeasure {ν : Measure 𝓧} {p : ℝ → 𝓧 → ℝ}
    {s : ℝ → 𝓧 → ℝ} (h : IsRegularDominatedFamily ν p s) (θ : ℝ) :
    IsProbabilityMeasure (modelMeasure ν p θ)

theorem score_integral_eq_zero {ν : Measure 𝓧} {p : ℝ → 𝓧 → ℝ} {s : ℝ → 𝓧 → ℝ}
    (h : IsRegularDominatedFamily ν p s) (θ : ℝ) :
    ∫ x, s θ x * p θ x ∂ν = 0

theorem integral_modelMeasure {ν : Measure 𝓧} {p : ℝ → 𝓧 → ℝ} {s : ℝ → 𝓧 → ℝ}
    (h : IsRegularDominatedFamily ν p s) (θ : ℝ) (F : 𝓧 → ℝ) :
    ∫ x, F x ∂(modelMeasure ν p θ) = ∫ x, F x * p θ x ∂ν

theorem fisherInformation_eq_integral_modelMeasure {ν : Measure 𝓧} {p : ℝ → 𝓧 → ℝ}
    {s : ℝ → 𝓧 → ℝ} (h : IsRegularDominatedFamily ν p s) (θ : ℝ) :
    fisherInformation ν p s θ = ∫ x, (s θ x) ^ 2 ∂(modelMeasure ν p θ)

theorem densityMean_eq_integral_modelMeasure {ν : Measure 𝓧} {p : ℝ → 𝓧 → ℝ}
    {s : ℝ → 𝓧 → ℝ} (h : IsRegularDominatedFamily ν p s) (T : 𝓧 → ℝ) (θ : ℝ) :
    densityMean ν p T θ = ∫ x, T x ∂(modelMeasure ν p θ)

theorem fisherInformation_nonneg {ν : Measure 𝓧} {p : ℝ → 𝓧 → ℝ} {s : ℝ → 𝓧 → ℝ}
    (h : IsRegularDominatedFamily ν p s) (θ : ℝ) :
    0 ≤ fisherInformation ν p s θ

theorem sq_integral_mul_le_integral_sq_mul_integral_sq {μ : Measure 𝓧} {f g : 𝓧 → ℝ}
    (hf : MemLp f 2 μ) (hg : MemLp g 2 μ) :
    (∫ x, f x * g x ∂μ) ^ 2 ≤ (∫ x, (f x) ^ 2 ∂μ) * (∫ x, (g x) ^ 2 ∂μ)

private theorem reverse_flatten_prod {G : Type*} [Group G] (blocks : List (List G)) :
    blocks.flatten.reverse.prod =
      (blocks.map fun block => block.reverse.prod).reverse.prod

theorem Path.DyadicC1AtDepth.piecewiseC1
    {x y : E} {gamma : Path x y} {n : ℕ}
    (hgamma : Path.DyadicC1AtDepth gamma n) : Path.PiecewiseC1 gamma

theorem BinaryOpenCoverSquareSubdivision.gridCellVertexInPiece_right_eq_basepoint
    {x₀ : X} {p : Path x₀ x₀}
    (F : Path.Homotopy p (Path.refl x₀)) {U V : Set X}
    (D : BinaryOpenCoverSquareSubdivision (pathHomotopySquare F) U V)
    (hxU : x₀ ∈ U) (hxV : x₀ ∈ V)
    (j : Fin D.steps) (b : Fin 2) :
    let last : Fin D.steps :=
      ⟨D.steps - 1, Nat.sub_lt D.steps_pos Nat.zero_lt_one⟩
    D.gridCellVertexInPiece last j 1 b =
      binaryOpenCoverBasepoint hxU hxV (D.label last j)

theorem compact_elim_finite_subcover {X : Type*} [TopologicalSpace X] {s : Set X}
    (hs : IsCompact s) {ι : Type*} (U : ι → Set X) (hUo : ∀ i : ι, IsOpen (U i))
    (hsU : s ⊆ ⋃ i, U i) : ∃ t : Finset ι, s ⊆ ⋃ i ∈ t, U i

theorem tychonoff {ι : Type*} {X : ι → Type*} [∀ i, TopologicalSpace (X i)]
    {s : ∀ i, Set (X i)} (hs : ∀ i, IsCompact (s i)) :
    IsCompact { x : ∀ i, X i | ∀ i, x i ∈ s i }

theorem Continuous.isClosed_preimage {τX : TextbookTopology X} {τY : TextbookTopology Y}
    {f : X → Y} (hf : Continuous τX τY f) {s : Set Y} (hs : τY.IsClosed s) :
    τX.IsClosed (f ⁻¹' s)

theorem continuous_iff_isClosed_preimage {τX : TextbookTopology X}
    {τY : TextbookTopology Y} {f : X → Y} :
    Continuous τX τY f ↔ ∀ s, τY.IsClosed s → τX.IsClosed (f ⁻¹' s)

theorem Continuous.comp {τX : TextbookTopology X} {τY : TextbookTopology Y}
    {τZ : TextbookTopology Z} {f : X → Y} {g : Y → Z}
    (hg : Continuous τY τZ g) (hf : Continuous τX τY f) :
    Continuous τX τZ (g ∘ f)

@[simp]
theorem isClosed_toMathlib (τ : TextbookTopology X) (s : Set X) :
    @_root_.IsClosed X τ.toMathlib s ↔ τ.IsClosed s

theorem toMathlib_symm {τX : TextbookTopology X} {a b : X} (γ : Path τX a b) :
    toMathlib γ.symm =
      @_root_.Path.symm X τX.toMathlib a b (toMathlib γ)

theorem toMathlib_trans {τX : TextbookTopology X} {a b c : X}
    (γ : Path τX a b) (δ : Path τX b c) :
    toMathlib (γ.trans δ) =
      @_root_.Path.trans X τX.toMathlib a b c (toMathlib γ) (toMathlib δ)

@[simp]
theorem fromMathlib_toMathlib {τX : TextbookTopology X} {τY : TextbookTopology Y}
    (e : Homeomorphism τX τY) : fromMathlib (toMathlib e) = e

theorem isOpen_induced_iff_exists (f : X → Y) (τY : TopologicalSpace Y) (s : Set X) :
    @_root_.IsOpen X (TopologicalSpace.induced f τY) s ↔
      ∃ v : Set Y, @_root_.IsOpen Y τY v ∧ f ⁻¹' v = s

theorem continuous_subtype_mk {τY : TextbookTopology Y} {τX : TextbookTopology X}
    {s : Set X} {f : Y → X} (hf : Continuous τY τX f) (hs : ∀ y, f y ∈ s) :
    Continuous τY (subspace s τX) (fun y ↦ ⟨f y, hs y⟩)

theorem isOpen_prod {τX : TextbookTopology X} {τY : TextbookTopology Y}
    {u : Set X} {v : Set Y} (hu : τX.IsOpen u) (hv : τY.IsOpen v) :
    (product τX τY).IsOpen (u ×ˢ v)

theorem continuous_prod_mk {W : Type*} {τW : TextbookTopology W}
    {τX : TextbookTopology X} {τY : TextbookTopology Y} {f : W → X} {g : W → Y}
    (hf : Continuous τW τX f) (hg : Continuous τW τY g) :
    Continuous τW (product τX τY) (fun w ↦ (f w, g w))

theorem path_symm_apply [TopologicalSpace X] {x y : X}
    (γ : _root_.Path x y) (t : unitInterval) :
    γ.symm t = γ (unitInterval.symm t)

@[ext]
theorem ext {τX : TextbookTopology X} {a b : X} {γ δ : Path τX a b}
    (h : ∀ t, γ t = δ t) : γ = δ

@[simp] theorem map_apply {τX : TextbookTopology X} {τY : TextbookTopology Y} {a b : X}
    (γ : Path τX a b) (f : X → Y) (hf : Continuous τX τY f) (t : UnitInterval) :
    γ.map f hf t = f (γ t)

@[simp]
theorem symm_apply {τX : TextbookTopology X} {a b : X}
    (γ : Path τX a b) (t : UnitInterval) : γ.symm t = γ t.reflect

theorem isPathConnected_image [TopologicalSpace X] [TopologicalSpace Y]
    {s : Set X} (hs : _root_.IsPathConnected s) {f : X → Y}
    (hf : _root_.Continuous f) : _root_.IsPathConnected (f '' s)

theorem Joined.map {Y : Type*} {τX : TextbookTopology X} {τY : TextbookTopology Y}
    {a b : X} {f : X → Y} (h : Joined τX a b) (hf : Continuous τX τY f) :
    Joined τY (f a) (f b)

theorem IsPathConnected.image {Y : Type*} {τX : TextbookTopology X}
    {τY : TextbookTopology Y} {s : Set X} {f : X → Y} (hs : IsPathConnected τX s)
    (hf : Continuous τX τY f) : IsPathConnected τY (f '' s)

theorem pathComponent_eq_of_mem_inter {a b : X}
    (h : (pathComponent tau a ∩ pathComponent tau b).Nonempty) :
    pathComponent tau a = pathComponent tau b

theorem image_pathComponent_subset {Y : Type*} {τY : TextbookTopology Y} {f : X → Y}
    (hf : Continuous tau τY f) (a : X) :
    f '' pathComponent tau a ⊆ pathComponent τY (f a)

theorem t2_tendsto_unique {X Y : Type*} [TopologicalSpace X] [T2Space X] [TopologicalSpace Y]
    {f : Y → X} {l : Filter Y} [l.NeBot] {a b : X}
    (ha : Filter.Tendsto f l (nhds a)) (hb : Filter.Tendsto f l (nhds b)) : a = b

theorem urysohn_lemma {X : Type*} [TopologicalSpace X] [NormalSpace X] {s t : Set X}
    (hs : IsClosed s) (ht : IsClosed t) (hd : Disjoint s t) :
    ∃ f : C(X, ℝ), Set.EqOn (⇑f) 0 s ∧ Set.EqOn (⇑f) 1 t ∧ ∀ x : X, (f x : ℝ) ∈ Set.Icc 0 1

theorem Path.Homotopy.hcomp_mapsTo
    {x₀ x₁ x₂ : X}
    {p₀ q₀ : Path x₀ x₁} {p₁ q₁ : Path x₁ x₂}
    (F : p₀.Homotopy q₀) (G : p₁.Homotopy q₁) {S : Set X}
    (hF : ∀ t s : unitInterval, F (t, s) ∈ S)
    (hG : ∀ t s : unitInterval, G (t, s) ∈ S) :
    ∀ t s : unitInterval, F.hcomp G (t, s) ∈ S

theorem Path.Homotopy.trans_mapsTo
    {x y : X} {p q r : Path x y}
    (F : p.Homotopy q) (G : q.Homotopy r) {S : Set X}
    (hF : ∀ t s : unitInterval, F (t, s) ∈ S)
    (hG : ∀ t s : unitInterval, G (t, s) ∈ S) :
    ∀ t s : unitInterval, F.trans G (t, s) ∈ S

private theorem exists_nat_pos_multiple_inv_lt (m : ℕ) (hm : 0 < m)
    {δ : ℝ} (hδ : 0 < δ) :
    ∃ N : ℕ, 0 < N ∧ m ∣ N ∧ (N : ℝ)⁻¹ < δ

private theorem Path.concatDyadicSegment_eq_of_ne_zero :
    ∀ {Y : Type*} [TopologicalSpace Y] {n : ℕ}
      (p : Fin (n + 2) → Y)
      (F : (i : Fin (n + 1)) → Path (p i.castSucc) (p i.succ))
      (i : Fin (n + 1)), i ≠ 0 → Path.concatDyadicSegment p F i = F i

private theorem Path.concatDyadicSegment_zero_eq_refl_trans :
    ∀ {Y : Type*} [TopologicalSpace Y] {n : ℕ}
      (p : Fin (n + 2) → Y)
      (F : (i : Fin (n + 1)) → Path (p i.castSucc) (p i.succ)),
      Path.concatDyadicSegment p F (0 : Fin (n + 1)) =
        (Path.refl (p (Fin.castSucc (0 : Fin (n + 1))))).trans (F 0)

@[simp]
theorem isOpen_toMathlib (τ : TextbookTopology X) (s : Set X) :
    @_root_.IsOpen X τ.toMathlib s ↔ τ.IsOpen s

theorem chartTransition_fst [PathConnectedSpace X] {y z : X}
    (U : SmallNeighborhood y) (V : SmallNeighborhood z) (q : ChartOverlap H U V) :
    (chartTransition H U V q).1 = (⟨q.1.1, q.1.2.2⟩ : V.carrier)

theorem continuous_chartTransition_fst [PathConnectedSpace X] {y z : X}
    (U : SmallNeighborhood y) (V : SmallNeighborhood z) :
    Continuous (fun q : ChartOverlap H U V => (chartTransition H U V q).1)

theorem chartInvDiscrete_chartToDiscrete [PathConnectedSpace X] {y : X}
    (U : SmallNeighborhood y) (q : ProjectionPreimage H U.carrier) :
    chartInvDiscrete H U (chartToDiscrete H U q) = q

theorem connectorChange_cast {x₀ z z' : X}
    (p q : Path x₀ z) (hz : z' = z) :
    connectorChange (p.cast rfl hz) (q.cast rfl hz) = connectorChange p q

theorem connectorChange_cast_proof_irrel {x₀ z z' : X}
    (p q : Path x₀ z) (hp hq : z' = z) :
    connectorChange (p.cast rfl hp) (q.cast rfl hq) = connectorChange p q

@[ext]
theorem ext {τX : TextbookTopology X} {τY : TextbookTopology Y} {f g : X → Y}
    {F G : Homotopy τX τY f g} (h : ∀ p, F p = G p) : F = G

@[simp] theorem refl_apply {τX : TextbookTopology X} {τY : TextbookTopology Y}
    {f : X → Y} (hf : Continuous τX τY f) (p : X × UnitInterval) :
    refl hf p = f p.1

theorem exteriorDerivative_squared_zero {E : Type u}
    [NormedAddCommGroup E] [NormedSpace ℝ E] {k : ℕ} {r : WithTop ℕ∞}
    (ω : DifferentialForm E k) (hω : ContDiff ℝ r ω)
    (hr : minSmoothness ℝ 2 ≤ r) :
    exteriorDerivative (exteriorDerivative ω) = 0

theorem alternatingWedge_add_left {E : Type u} [AddCommGroup E] [Module ℝ E] {k l : ℕ}
    (a₁ a₂ : E [⋀^Fin k]→ₗ[ℝ] ℝ) (b : E [⋀^Fin l]→ₗ[ℝ] ℝ) :
    alternatingWedge (a₁ + a₂) b = alternatingWedge a₁ b + alternatingWedge a₂ b

theorem alternatingWedge_add_right {E : Type u} [AddCommGroup E] [Module ℝ E] {k l : ℕ}
    (a : E [⋀^Fin k]→ₗ[ℝ] ℝ) (b₁ b₂ : E [⋀^Fin l]→ₗ[ℝ] ℝ) :
    alternatingWedge a (b₁ + b₂) = alternatingWedge a b₁ + alternatingWedge a b₂

theorem algebraicFormWedge_zero_left {E : Type u} [AddCommGroup E] [Module ℝ E] {k l : ℕ}
    (η : AlgebraicDifferentialForm E l) :
    algebraicFormWedge (0 : AlgebraicDifferentialForm E k) η = 0

theorem algebraicFormWedge_zero_right {E : Type u} [AddCommGroup E] [Module ℝ E] {k l : ℕ}
    (ω : AlgebraicDifferentialForm E k) :
    algebraicFormWedge ω (0 : AlgebraicDifferentialForm E l) = 0

theorem continuousAlternatingWedge_apply {E : Type u}
    [NormedAddCommGroup E] [NormedSpace ℝ E] {k l : ℕ}
    (a : E [⋀^Fin k]→L[ℝ] ℝ) (b : E [⋀^Fin l]→L[ℝ] ℝ) (v : Fin (k + l) → E) :
    continuousAlternatingWedge a b v =
      alternatingWedge a.toAlternatingMap b.toAlternatingMap v

theorem continuousAlternatingWedge_add_left {E : Type u}
    [NormedAddCommGroup E] [NormedSpace ℝ E] {k l : ℕ}
    (a₁ a₂ : E [⋀^Fin k]→L[ℝ] ℝ) (b : E [⋀^Fin l]→L[ℝ] ℝ) :
    continuousAlternatingWedge (a₁ + a₂) b =
      continuousAlternatingWedge a₁ b + continuousAlternatingWedge a₂ b

theorem continuousAlternatingWedge_add_right {E : Type u}
    [NormedAddCommGroup E] [NormedSpace ℝ E] {k l : ℕ}
    (a : E [⋀^Fin k]→L[ℝ] ℝ) (b₁ b₂ : E [⋀^Fin l]→L[ℝ] ℝ) :
    continuousAlternatingWedge a (b₁ + b₂) =
      continuousAlternatingWedge a b₁ + continuousAlternatingWedge a b₂

theorem continuousAlternatingWedge_zero_left {E : Type u}
    [NormedAddCommGroup E] [NormedSpace ℝ E] {k l : ℕ}
    (b : E [⋀^Fin l]→L[ℝ] ℝ) :
    continuousAlternatingWedge (0 : E [⋀^Fin k]→L[ℝ] ℝ) b = 0

theorem continuousAlternatingWedge_zero_right {E : Type u}
    [NormedAddCommGroup E] [NormedSpace ℝ E] {k l : ℕ}
    (a : E [⋀^Fin k]→L[ℝ] ℝ) :
    continuousAlternatingWedge a (0 : E [⋀^Fin l]→L[ℝ] ℝ) = 0

theorem continuousAlternatingWedge_smul_left {E : Type u}
    [NormedAddCommGroup E] [NormedSpace ℝ E] {k l : ℕ}
    (c : ℝ) (a : E [⋀^Fin k]→L[ℝ] ℝ) (b : E [⋀^Fin l]→L[ℝ] ℝ) :
    continuousAlternatingWedge (c • a) b = c • continuousAlternatingWedge a b

theorem continuousAlternatingWedge_smul_right {E : Type u}
    [NormedAddCommGroup E] [NormedSpace ℝ E] {k l : ℕ}
    (c : ℝ) (a : E [⋀^Fin k]→L[ℝ] ℝ) (b : E [⋀^Fin l]→L[ℝ] ℝ) :
    continuousAlternatingWedge a (c • b) = c • continuousAlternatingWedge a b

theorem continuousAlternatingWedge_norm_le {E : Type u}
    [NormedAddCommGroup E] [NormedSpace ℝ E] {k l : ℕ}
    (a : E [⋀^Fin k]→L[ℝ] ℝ) (b : E [⋀^Fin l]→L[ℝ] ℝ) :
    ‖continuousAlternatingWedge a b‖ ≤ shuffleCount k l * ‖a‖ * ‖b‖

theorem wedgeContinuousBilinear_apply {E : Type u}
    [NormedAddCommGroup E] [NormedSpace ℝ E] {k l : ℕ}
    (a : E [⋀^Fin k]→L[ℝ] ℝ) (b : E [⋀^Fin l]→L[ℝ] ℝ) :
    wedgeContinuousBilinear k l a b = continuousAlternatingWedge a b

theorem normalizedAlternatingSpace_differentiableAt {E : Type u}
    [NormedAddCommGroup E] [NormedSpace ℝ E] {k : ℕ}
    {ω : DifferentialForm E k} {x : E} (hω : DifferentiableAt ℝ ω x) :
    DifferentiableAt ℝ (fun y ↦ toNormalizedAlternatingSpace k (ω y)) x

theorem differentiableAt_formWedge {E : Type u}
    [NormedAddCommGroup E] [NormedSpace ℝ E] {k l : ℕ}
    {ω : DifferentialForm E k} {η : DifferentialForm E l} {x : E}
    (hω : DifferentiableAt ℝ ω x) (hη : DifferentiableAt ℝ η x) :
    DifferentiableAt ℝ (formWedge ω η) x

theorem totalDerivative_chain {f : E → F} {g : F → G}
    {x : E} {A : E →L[ℝ] F} {B : F →L[ℝ] G}
    (hf : HasFDerivAt f A x) (hg : HasFDerivAt g B (f x)) :
    HasFDerivAt (g ∘ f) (B.comp A) x

theorem gradient_totalDerivative {f : H → ℝ} {x grad : H}
    (h : HasGradientAt f grad x) :
    HasFDerivAt f (InnerProductSpace.toDual ℝ H grad) x

theorem directionalDerivative_eq_inner_gradient {f : H → ℝ} {x grad v : H}
    (h : HasGradientAt f grad x) :
    DirectionalDerivative f x v = inner ℝ grad v

theorem partialDerivative_eq {n m : ℕ} {f : (Fin n → ℝ) → (Fin m → ℝ)}
    {x : Fin n → ℝ} {A : (Fin n → ℝ) →L[ℝ] (Fin m → ℝ)}
    (h : HasFDerivAt f A x) (j : Fin n) :
    partialDerivative f x j = A (Pi.single j 1)

theorem jacobian_apply {n m : ℕ} {f : (Fin n → ℝ) → (Fin m → ℝ)}
    {x : Fin n → ℝ} {A : (Fin n → ℝ) →L[ℝ] (Fin m → ℝ)}
    (h : HasFDerivAt f A x) (i : Fin m) (j : Fin n) :
    jacobian f x i j = A (Pi.single j 1) i

theorem totalDerivative_apply_eq_jacobian_mulVec {n m : ℕ}
    {f : (Fin n → ℝ) → (Fin m → ℝ)} {x v : Fin n → ℝ}
    {A : (Fin n → ℝ) →L[ℝ] (Fin m → ℝ)} (h : HasFDerivAt f A x) :
    A v = jacobian f x *ᵥ v

theorem jacobian_chain {n m p : ℕ}
    {f : (Fin n → ℝ) → (Fin m → ℝ)} {g : (Fin m → ℝ) → (Fin p → ℝ)}
    {x : Fin n → ℝ}
    {A : (Fin n → ℝ) →L[ℝ] (Fin m → ℝ)}
    {B : (Fin m → ℝ) →L[ℝ] (Fin p → ℝ)}
    (hf : HasFDerivAt f A x) (hg : HasFDerivAt g B (f x)) :
    jacobian (g ∘ f) x = jacobian g (f x) * jacobian f x

theorem hessian_symmetric {n : ℕ} {f : (Fin n → ℝ) → ℝ} {x : Fin n → ℝ}
    (hf : ContDiffAt ℝ 2 f x) :
    SandronesLibrary.LinearAlgebra.Matrix.IsSymmetric (hessian f x)

theorem multivariable_taylor_first_order {E F : Type*}
    [NormedAddCommGroup E] [NormedSpace ℝ E]
    [NormedAddCommGroup F] [NormedSpace ℝ F] [CompleteSpace F]
    {f : E → F} {x y : E}
    (hf : ∀ t ∈ Set.Icc (0 : ℝ) 1, ContDiffAt ℝ 1 f (x + t • y)) :
    f (x + y) = f x + ∫ t in (0 : ℝ)..1, fderiv ℝ f (x + t • y) y

lemma func_lim_congr {f g : ℝ → ℝ} {a : ℝ} {L : ℝ}
    (hfg : ∀ᶠ x in 𝓝[≠] a, f x = g x)
    (hf : Tendsto f (𝓝[≠] a) (𝓝 L)) : Tendsto g (𝓝[≠] a) (𝓝 L)

lemma func_lim_add {f g : ℝ → ℝ} {a L M : ℝ}
    (hf : Tendsto f (𝓝[≠] a) (𝓝 L)) (hg : Tendsto g (𝓝[≠] a) (𝓝 M)) :
    Tendsto (fun x => f x + g x) (𝓝[≠] a) (𝓝 (L + M))

lemma func_lim_sub {f g : ℝ → ℝ} {a L M : ℝ}
    (hf : Tendsto f (𝓝[≠] a) (𝓝 L)) (hg : Tendsto g (𝓝[≠] a) (𝓝 M)) :
    Tendsto (fun x => f x - g x) (𝓝[≠] a) (𝓝 (L - M))

lemma func_lim_mul {f g : ℝ → ℝ} {a L M : ℝ}
    (hf : Tendsto f (𝓝[≠] a) (𝓝 L)) (hg : Tendsto g (𝓝[≠] a) (𝓝 M)) :
    Tendsto (fun x => f x * g x) (𝓝[≠] a) (𝓝 (L * M))

lemma func_lim_le {f g : ℝ → ℝ} {a L M : ℝ}
    (hf : Tendsto f (𝓝[≠] a) (𝓝 L)) (hg : Tendsto g (𝓝[≠] a) (𝓝 M))
    (hfg : ∀ᶠ x in 𝓝[≠] a, f x ≤ g x) : L ≤ M

theorem func_lim_comp {f : ℝ → ℝ} {g : ℝ → ℝ} {a L : ℝ}
    (hf : Tendsto f (𝓝[≠] a) (𝓝 L)) (hg : ContinuousAt g L) :
    Tendsto (fun x => g (f x)) (𝓝[≠] a) (𝓝 (g L))

theorem continuousOn_integrableOn_closedRectangle {f : ℝ × ℝ → ℝ} {a b c d : ℝ}
    (hf : ContinuousOn f (closedRectangle a b c d)) :
    IntegrableOn f (closedRectangle a b c d) (volume.prod volume)

theorem isJordanMeasurable_mass_nonneg {n : ℕ} {ρ : JordanEuc n → ℝ}
    {D : Set (JordanEuc n)} (hD : IsJordanMeasurable D) (hρ : ∀ x ∈ D, 0 ≤ ρ x) :
    0 ≤ mass ρ D

